using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using Unity.XR.CoreUtils;using UnityEngine.XR;using UnityEngine.XR.Interaction.Toolkit.Interactables;using UnityEngine.XR.Interaction.Toolkit.Inputs.Readers;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Net;using LighthouseKeepers.Gameplay.Interaction;using LighthouseKeepers.Core;
public sealed class AuthProbe:MonoBehaviour {
 static WatchDemoController W=>UnityEngine.Object.FindAnyObjectByType<WatchDemoController>();
 HandRig hand;XRSimpleInteractable target;
 public static object Inspect(){var r=UnityEngine.Object.FindAnyObjectByType<WatchRadioConsole>();return new{radio=r.transform.position.ToString(),rotation=r.transform.eulerAngles.ToString(),children=r.GetComponentsInChildren<Renderer>().Select(x=>new{name=x.name,p=r.transform.InverseTransformPoint(x.bounds.center).ToString(),size=x.bounds.size.ToString()}).ToArray(),controls=r.controls.Select(x=>new{x.name,p=x.transform.localPosition.ToString(),world=x.transform.position.ToString()}).ToArray()};}
 public static object Ready(){var s=W.State;s.EngageWatch();s.CompleteRepair();s.Engine.Reset(.8f,0,true);s.Grid.Reset(100,15,true);if(!s.Radio.MainOn)s.Radio.ToggleMain();var radio=UnityEngine.Object.FindAnyObjectByType<WatchRadioConsole>();s.Radio.Tune(radio.program.targetMHz);s.Radio.Tick(5,true);var narrator=UnityEngine.Object.FindAnyObjectByType<HarborRadio>();narrator.enabled=false;typeof(HarborRadio).GetProperty("Age").SetValue(narrator,1000f);return Facts();}
 public static object Facts(){var w=W;var a=w.GetComponent<RadioAuthentication>();return new{day=w.State.Day,failed=w.State.Failed,powered=w.State.HasPower(PowerCircuit.Radio),main=w.State.Radio.MainOn,locked=w.State.Radio.Locked,frame=w.State.Authenticity.Capture(),reply=a.Reply,caption=a.Caption,code=CodeSource.CodeText(w.State.Radio),duty=w.CurrentDuty.ToString(),protocol=LighthouseKeepers.Core.CrewNetworkVersion.Matchmaking};}
 public static object ForceFalse(){var s=W.State;s.Authenticity.Tick(20,true,true,true,false,false,false);s.Authenticity.Tick(1,true,true,true,true,false,false);return Facts();}
 public static object Grab(string cmd,string distance){Release();var r=W.GetComponent<RadioAuthentication>();var target=(XRSimpleInteractable)r.Control(int.Parse(cmd));var rig=UnityEngine.Object.FindAnyObjectByType<XROrigin>();rig.MoveCameraToWorldLocation(target.transform.position+target.transform.forward*.55f+Vector3.up*.45f);foreach(var m in rig.GetComponentsInChildren<UnityEngine.XR.Interaction.Toolkit.Inputs.XRInputModalityManager>(true))m.enabled=false;
 var c=new GameObject("Authentication hand fixture").AddComponent<AuthProbe>();c.hand=rig.GetComponentsInChildren<HandRig>(true).Single(x=>x.Node==XRNode.RightHand);c.hand.transform.parent.gameObject.SetActive(true);foreach(var t in c.hand.transform.parent.GetComponents<UnityEngine.InputSystem.XR.TrackedPoseDriver>())t.enabled=false;c.target=target;c.hand.transform.parent.position=target.transform.position+(distance=="far"?Vector3.up*2:Vector3.zero);c.Invoke(nameof(Begin),.7f);return true;}
 void Begin(){var d=hand.Direct;d.selectInput=new XRInputButtonReader("auth test",inputSourceMode:XRInputButtonReader.InputSourceMode.ManualValue);d.selectInput.manualPerformed=true;d.selectInput.manualValue=1;d.StartManualInteraction((IXRSelectInteractable)target);}
 public static object Release(){foreach(var h in UnityEngine.Object.FindObjectsByType<HandRig>(FindObjectsSortMode.None))if(h.Direct&&h.Direct.hasSelection)h.Direct.EndManualInteraction();var g=GameObject.Find("Authentication hand fixture");if(g)UnityEngine.Object.Destroy(g);return true;}
 public static object Capture(string file){var r=UnityEngine.Object.FindAnyObjectByType<WatchRadioConsole>();var center=r.transform.TransformPoint(new Vector3(-.2f,1.25f,.3f));return CaptureAt(file,center+r.transform.forward*2+Vector3.up*.3f,center);}
 static object CaptureAt(string file,Vector3 eye,Vector3 target){var rig=UnityEngine.Object.FindAnyObjectByType<XROrigin>();var c=new GameObject("Radio receipt camera").AddComponent<Camera>();c.CopyFrom(rig.Camera);c.enabled=false;c.fieldOfView=58;c.transform.SetPositionAndRotation(eye,Quaternion.LookRotation(target-eye));var old=RenderTexture.active;var rt=RenderTexture.GetTemporary(1400,1100,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(1400,1100,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1400,1100),0,0);t.Apply();File.WriteAllBytes(file,t.EncodeToPNG());RenderTexture.active=old;c.targetTexture=null;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.Destroy(t);UnityEngine.Object.Destroy(c.gameObject);return true;}
}
